      answer: 1,
      explanations: [
        "\u591A\u91CD\u30EC\u30D9\u30EB\u30DA\u30FC\u30B8\u30F3\u30B0\u3092\u7528\u3044\u3066\u3082\u30DA\u30FC\u30B8\u30C6\u30FC\u30D6\u30EB\u81EA\u4F53\u306F\u5FC5\u8981\u3067\u3042\u308A\u3001\u4E0D\u8981\u306B\u306A\u308B\u308F\u3051\u3067\u306F\u306A\u3044\u3002",
        "\u6B63\u3057\u3044\u3002\u591A\u91CD\u30EC\u30D9\u30EB\u30DA\u30FC\u30B8\u30F3\u30B0\u3068\u4EEE\u60F3\u8A18\u61B6\u3092\u7D44\u307F\u5408\u308F\u305B\u308B\u3053\u3068\u3067\u3001\u73FE\u5728\u4F7F\u308F\u308C\u3066\u3044\u306A\u3044\u53E4\u3044\u30DA\u30FC\u30B8\u30C6\u30FC\u30D6\u30EB\u81EA\u4F53\u3082\u4EEE\u60F3\u8A18\u61B6\u306E\u4ED5\u7D44\u307F\u3067\u4E3B\u8A18\u61B6\u304B\u3089\u30DA\u30FC\u30B8\u30A2\u30A6\u30C8\u3067\u304D\u3001\u4E3B\u8A18\u61B6\u5185\u306E\u30DA\u30FC\u30B8\u30C6\u30FC\u30D6\u30EB\u306E\u5927\u304D\u3055\u3092\u4E8B\u5B9F\u4E0A\u7121\u8996\u3067\u304D\u308B\u3002",
        "\u30DA\u30FC\u30B8\u30B5\u30A4\u30BA\u3092\u5927\u304D\u304F\u3059\u308B\u3053\u3068\u306F\u3001\u3053\u306E\u8A2D\u554F\u3067\u8AAC\u660E\u3055\u308C\u3066\u3044\u308B\u4ED5\u7D44\u307F\u306E\u76F4\u63A5\u306E\u7406\u7531\u3067\u306F\u306A\u3044\u3002",
        "CPU\u306E\u51E6\u7406\u901F\u5EA6\u306E\u5411\u4E0A\u306F\u3001\u30DA\u30FC\u30B8\u30C6\u30FC\u30D6\u30EB\u306E\u30B5\u30A4\u30BA\u7BA1\u7406\u306E\u4ED5\u7D44\u307F\u3068\u306F\u76F4\u63A5\u95A2\u4FC2\u3057\u306A\u3044\u3002"
      ]
